func newChatCmd(flags *rootFlags) *cobra.Command {
	var (
		maxTokens   int
		temperature float64
	)
	cmd := &cobra.Command{
		Use:   "chat <model-id> <prompt>",
		Short: "Send an OpenAI-compatible chat completion",
		Args:  cobra.MinimumNArgs(1),
		Example: `  orcarouter-pp-cli chat orcarouter/fusion-flash "summarize this"
  orcarouter-pp-cli chat orcarouter/free "hello" --max-tokens 50
  orcarouter-pp-cli chat orcarouter/fusion "explain in one line" --temperature 0.2 --json`,
		RunE: func(cmd *cobra.Command, args []string) error {
			model := args[0]
			prompt := strings.Join(args[1:], " ")
			if prompt == "" {
				return fmt.Errorf("prompt is required")
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			req := client.ChatRequest{
				Model:       model,
				Messages:    []client.ChatMessage{{Role: "user", Content: prompt}},
				MaxTokens:   maxTokens,
				Temperature: temperature,
			}
			var resp client.ChatResponse
			if err := c.PostJSON("/chat/completions", req, &resp); err != nil {
				return err
			}

			if flags.asJSON {
				return flags.printJSON(cmd, resp)
			}

			for _, choice := range resp.Choices {
				content := choice.Message.Content
				if content == "" {
					content = "(no content)"
				}
				fmt.Fprintln(cmd.OutOrStdout(), content)
			}
			if !flags.compact {
				fmt.Fprintf(cmd.OutOrStdout(), "\n[model=%s tokens=%d total_tokens=%d]\n", resp.Model, resp.Usage.TotalTokens, resp.Usage.TotalTokens)
			}
			return nil
		},
	}
	cmd.Flags().IntVar(&maxTokens, "max-tokens", 0, "Maximum tokens to generate")
	cmd.Flags().Float64Var(&temperature, "temperature", 0, "Sampling temperature")
	return cmd
}
